"""Build an offline slide-card document using only the Python standard library."""
from pathlib import Path
import html
import json

HERE = Path(__file__).resolve().parent
data = json.loads((HERE / 'deck-content.json').read_text())
esc = html.escape
cards = []
for number, section in enumerate(data['content']['sections'], 1):
    title = esc(section['heading']).replace('\n','<br>')
    subtitle = esc(section.get('subtitle',''))
    visual = section.get('visual')
    body = ''
    if number == 1:
        body = '<p class="lead">Which account should I review first?<br>What evidence supports the priority?<br>Which policy applies?</p><p class="disclosure">Demonstration dataset · INR display assumption</p>'
    elif number == 2:
        body = '<div class="two"><div class="stat"><b>63%</b><p>Lacked or were unsure of suitable data-management practices for AI.</p><small>Gartner · July 2024 survey · n=1,203</small></div><div class="stat"><b>21%</b><p>Reported fundamental redesign of at least some workflows.</p><small>McKinsey · respondents using generative AI</small></div></div><p class="disclosure">Independent findings with different populations. Sources and context are in presenter notes.</p>'
    elif visual:
        src = '../media/screenshots/executive-snapshot.png' if visual == 'dashboard' else f'../media/diagrams/{visual}.svg'
        alt = {'architecture':'Separate Spark-agent and AILH-OAC serving paths', 'dashboard':'Verified December 2024 OAC dashboard', 'agent-flow':'Supervisor with portfolio SQL, investigation SQL, policy RAG and brief executors'}[visual]
        body = f'<figure><img src="{src}" alt="{alt}" loading="lazy"></figure>'
        if visual == 'dashboard':
            body += '<div class="mini-kpis"><span><b>12,699</b>transactions</span><span><b>INR 31.64M</b>gross activity</span><span><b>38.85%</b>count flag rate</span></div><p class="disclosure">Screening flags are not confirmed fraud or losses. Frozen OAC reference; do not blend with older agent snapshots.</p>'
    elif 'table' in section:
        t=section['table'];body='<div class="table-scroll"><table><thead><tr>'+''.join(f'<th>{esc(x)}</th>' for x in t['columns'])+'</tr></thead><tbody>'
        body+=''.join('<tr>'+''.join(f'<td>{esc(x)}</td>' for x in row)+'</tr>' for row in t['rows'])+'</tbody></table></div>'
        body+='<p class="disclosure">Initial publication verified. Changed-data replacement requires further hosted validation. Index DDL is supplied separately.</p>'
    elif 'columns' in section:
        groups=list(section['columns'].values())
        body=f'<div class="columns columns-{len(groups)}">'+''.join('<div class="column"><h3>'+esc(v[0])+'</h3>'+''.join('<p>'+esc(x)+'</p>' for x in v[1:])+'</div>' for v in groups)+'</div>'
        if number==4:body+='<p class="disclosure">The separate ML pipeline uses rule-derived labels. Its predictions are not the source of the agent queue.</p>'
        if number==8:body+='<p class="disclosure">Signed transport and a SQL response were verified historically. Fresh hybrid evidence reconciliation remains required.</p>'
    elif section['purpose']=='timeline_slide':
        body='<ol class="steps">'+''.join('<li><b>'+esc(x.split('\n')[0])+'</b><span>'+esc(x.split('\n')[1])+'</span></li>' for x in section['bullets'])+'</ol><div class="resource-links"><a href="../docs/user-guide.md">User guide</a><a href="../docs/hosted-acceptance.md">Acceptance criteria</a><a href="../video/README.md">Recording package</a></div>'
    if number==10:
        body='<img class="closing-logo" src="../media/brand/oracle-wordmark.png" alt="Oracle">'
    note = esc(section.get('notes','')).replace('\n','<br>')
    classes='slide cover' if number==1 else ('slide closing' if number==10 else 'slide')
    cards.append(f'<section class="{classes}" id="slide-{number}" aria-labelledby="title-{number}"><header><span class="eyebrow">FINANCIAL INVESTIGATION COPILOT <span>{number:02d} / 10</span></span><h2 id="title-{number}">{title}</h2><p class="subtitle">{subtitle}</p></header><div class="content">{body}</div><details class="notes"><summary>Presenter notes and sources</summary><p>{note}</p></details></section>')

document='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Financial Investigation Copilot — slide cards</title><style>
:root{--ink:#312d2a;--muted:#70675e;--red:#c74634;--bg:#f7f5f1;--line:#ddd7cf;--blue:#315f70}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.55 Arial,Helvetica,sans-serif}.toolbar{position:sticky;top:0;z-index:20;display:flex;align-items:center;gap:10px;padding:14px 4vw;background:#fff;border-bottom:1px solid var(--line);flex-wrap:wrap}.toolbar img{width:112px;height:auto;margin-right:auto}.toolbar button{border:1px solid var(--line);border-radius:6px;background:#fff;color:var(--ink);padding:8px 12px;font:inherit;cursor:pointer}.toolbar button.primary{background:var(--red);color:white;border-color:var(--red)}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid var(--blue);outline-offset:3px}#counter{font-size:13px;color:var(--muted);min-width:48px}main{max-width:1440px;margin:auto;padding:36px 4vw 80px;display:grid;gap:32px}.slide{scroll-margin-top:95px;position:relative;background:#fff;border:1px solid var(--line);border-radius:14px;padding:32px 42px;box-shadow:0 8px 30px #312d2a08;overflow:hidden}.slide:before{content:"";position:absolute;left:0;top:0;width:6px;height:100%;background:var(--red)}.eyebrow{font-size:11px;font-weight:bold;letter-spacing:.12em;color:var(--red);display:flex;justify-content:space-between}.eyebrow span{color:var(--muted)}h2{font-size:clamp(24px,3vw,38px);line-height:1.15;letter-spacing:-.025em;margin:18px 0 10px;font-weight:700}.subtitle{font-size:17px;color:var(--muted);margin:0 0 25px}.content{margin-top:12px}.lead{font-size:clamp(25px,3vw,39px);line-height:1.5;max-width:900px;margin:34px 0}.cover{background:linear-gradient(110deg,#fff 0%,#fff 60%,#f0ebe4 100%);padding-bottom:42px}.cover h2{font-size:clamp(36px,5vw,62px);max-width:1000px}.two,.columns{display:grid;grid-template-columns:repeat(2,1fr);gap:25px}.columns-3{grid-template-columns:repeat(3,1fr)}.stat,.column{background:#f7f5f1;padding:28px;border-radius:10px;border:1px solid var(--line)}.stat b{display:block;font-size:64px;line-height:1;color:var(--red)}.stat p{font-size:22px;line-height:1.4;max-width:450px}.stat small{color:var(--muted)}.column h3{color:var(--red);font-size:18px;margin:0 0 18px}.column p{font-size:21px;margin:12px 0}figure{margin:0}figure img{width:100%;height:auto;max-height:570px;object-fit:contain;display:block}.disclosure{font-size:12px;color:var(--muted);margin:22px 0 4px}.mini-kpis{display:flex;gap:36px;flex-wrap:wrap;margin:20px 0}.mini-kpis span{display:grid;color:var(--muted);font-size:12px}.mini-kpis b{font-size:25px;color:var(--ink)}table{border-collapse:collapse;width:100%;font-size:20px}th{text-align:left;background:#312d2a;color:white;padding:14px 20px}td{padding:18px 20px;border-bottom:1px solid var(--line)}tbody tr:nth-child(even){background:#f7f5f1}.table-scroll{overflow:auto}.steps{display:grid;grid-template-columns:repeat(5,1fr);gap:16px;padding:0;counter-reset:step;list-style:none}.steps li{counter-increment:step;background:#f7f5f1;border-top:4px solid var(--red);padding:24px 16px;border-radius:8px}.steps li:before{content:counter(step,decimal-leading-zero);display:block;color:var(--red);font-size:14px;margin-bottom:24px}.steps b{font-size:22px;display:block}.steps span{display:block;color:var(--muted);margin-top:12px}.resource-links{display:flex;gap:20px;flex-wrap:wrap;margin:30px 0}.resource-links a{color:var(--blue)}.notes{border-top:1px solid var(--line);margin-top:26px;padding-top:12px;font-size:13px;color:var(--muted)}summary{cursor:pointer}.notes p{max-width:100%;overflow-wrap:anywhere}.closing{min-height:420px;display:grid;place-items:center}.closing header,.closing .notes{display:none}.closing-logo{width:340px;max-width:70vw;height:auto}.footer{max-width:1440px;margin:auto;padding:0 4vw 30px;color:var(--muted);font-size:12px}.progress{position:fixed;bottom:0;left:0;height:4px;background:var(--red);width:10%;z-index:30}.presenting main{max-width:100%;padding:18px 3vw}.presenting .slide{display:none;min-height:calc(100vh - 115px)}.presenting .slide.active{display:block}.presenting .slide.closing.active{display:grid}.presenting .footer{display:none}.hide-notes .notes{display:none}@media(max-width:750px){.slide{padding:25px 22px}.two,.columns,.columns-3,.steps{grid-template-columns:1fr}.stat b{font-size:50px}.toolbar{padding:10px}.toolbar img{width:80px}.toolbar button{font-size:12px;padding:7px}.column p{font-size:18px}table{font-size:15px}.steps li:before{margin-bottom:8px}}@media print{body{background:white}.toolbar,.footer,.progress,.notes{display:none!important}main,.presenting main{padding:0;display:block}.slide,.presenting .slide{display:block!important;border:0;border-radius:0;box-shadow:none;min-height:0;height:180mm;page-break-after:always;padding:12mm}.slide.closing{display:grid!important}.slide:last-child{page-break-after:auto}h2{font-size:26px}.lead{font-size:28px}figure img{max-height:120mm}.stat b{font-size:48px}.stat p,td,th,.column p{font-size:17px}@page{size:A4 landscape;margin:10mm}}
</style></head><body><nav class="toolbar" aria-label="Presentation controls"><img src="../media/brand/oracle-wordmark.png" alt="Oracle"><button id="prev" aria-label="Previous slide">←</button><span id="counter" aria-live="polite">1 / 10</span><button id="next" aria-label="Next slide">→</button><button id="mode" class="primary" aria-pressed="false">Present</button><button id="notes" aria-pressed="true">Notes</button><button id="print">Print / PDF</button></nav><main>'''+''.join(cards)+'''</main><footer class="footer">Abhijit Khuperkar · 18 October 2026 · Independent reference implementation. Oracle trademarks belong to their owner.<br>← / → to navigate · P to present · N to toggle notes · Esc for slide cards</footer><div class="progress" aria-hidden="true"></div><script>
const cards=[...document.querySelectorAll('.slide')];let current=0;let presenting=false;
function show(n){current=Math.max(0,Math.min(cards.length-1,n));cards.forEach((x,i)=>x.classList.toggle('active',i===current));document.querySelector('#counter').textContent=`${current+1} / ${cards.length}`;document.querySelector('.progress').style.width=`${(current+1)/cards.length*100}%`;document.querySelector('#prev').disabled=current===0;document.querySelector('#next').disabled=current===cards.length-1;if(!presenting)cards[current].scrollIntoView({behavior:'smooth',block:'start'});}
function mode(value){presenting=value;document.body.classList.toggle('presenting',value);document.querySelector('#mode').textContent=value?'Slide cards':'Present';document.querySelector('#mode').setAttribute('aria-pressed',value);show(current);}
document.querySelector('#prev').onclick=()=>show(current-1);document.querySelector('#next').onclick=()=>show(current+1);document.querySelector('#mode').onclick=()=>mode(!presenting);document.querySelector('#notes').onclick=()=>{const hidden=document.body.classList.toggle('hide-notes');document.querySelector('#notes').setAttribute('aria-pressed',!hidden);};document.querySelector('#print').onclick=()=>window.print();
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1);}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1);}if(e.key==='Home')show(0);if(e.key==='End')show(cards.length-1);if(e.key==='Escape')mode(false);if(e.key.toLowerCase()==='p')mode(!presenting);if(e.key.toLowerCase()==='n')document.querySelector('#notes').click();});
const initial=Number(location.hash.replace('#slide-',''))-1;if(initial>=0&&initial<cards.length)current=initial;cards[current].classList.add('active');document.querySelector('#counter').textContent=`${current+1} / ${cards.length}`;
</script></body></html>'''
(HERE/'index.html').write_text(document)
print('Built offline HTML slide cards: 10 slides, keyboard controls, notes and print layout.')
